/// <summary>
/// Virtual-time watchdog test: inactivity deadline fires after burst + silence.
/// We advance the manual clock past the deadline in one step, then let the
/// async continuation run via a brief real-time yield so the watchdog’s
/// internal poll loop sees the expired deadline immediately.
/// </summary>
public async Task WaitAsync_BurstThenTotalSilence_FiresAtInactivityDeadline()
{
    const int inactivityTimeoutMs = 2_000;
    var time = new ManualTimeProvider();
    using var kill = new CancellationTokenSource();
    var watchdog = new ActivityWatchdog(
        firstOutputTimeoutMs: 1_000,
        inactivityTimeoutMs: inactivityTimeoutMs,
        absoluteCeilingMs: 0,
        kill, timeProvider: time);

    // Burst: two pulses close together, then total silence.
    watchdog.Pulse("stdout");
    time.Advance(TimeSpan.FromMilliseconds(50));
    watchdog.Pulse("trace");

    // Start the watchdog and jump past the inactivity deadline.
    var watchdogTask = watchdog.WaitAsync(CancellationToken.None);

    // Advance virtual time well past the deadline so the watchdog's
    // poll loop exits on its next iteration.
    time.Advance(TimeSpan.FromMilliseconds(inactivityTimeoutMs + 200));

    // Pump the async state machine just enough for the deadline check
    // to run — a handful of real-time ticks, not 120 × Task.Yield.
    for (var i = 0; i < 5 && !watchdogTask.IsCompleted; i++)
        await Task.Delay(1);

    var result = await watchdogTask;

    Assert.Equal(ActivityWatchdog.Outcome.FiredStall, result.Outcome);
    Assert.Equal("trace", result.LastPulseSource);
    Assert.True(result.SilenceMs >= inactivityTimeoutMs);
    Assert.True(kill.IsCancellationRequested);
}

